input.content:
:root {
  --bg1: #07141d;
  --bg2: #101f2d;
  --panel: rgba(12, 25, 34, 0.8);
  --panel-strong: rgba(18, 35, 45, 0.92);
  --line: rgba(137, 214, 255, 0.35);
  --text: #ebf7ff;
  --muted: #9ad7ea;
  --gold: #f9d67b;
  --accent: #7ee7ff;
  --success: #7fe7a9;
  --danger: #ff7d7d;
  --shadow: rgba(0, 0, 0, 0.28);
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  min-height: 100%;
  background:
    radial-gradient(circle at 50% 0%, rgba(123, 206, 255, 0.2), transparent 30%),
    linear-gradient(180deg, var(--bg1), var(--bg2));
  color: var(--text);
  font-family: Inter, "Segoe UI", sans-serif;
}
body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 20px;
}
.game-shell {
  width: min(100%, 1100px);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: 0 28px 60px var(--shadow);
  padding: 16px 18px 18px;
  backdrop-filter: blur(4px);
}
.topbar {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 20px;
  margin-bottom: 12px;
}
.eyebrow {
  margin: 0 0 4px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 11px;
}
h1 {
  margin: 0;
  font-size: clamp(22px, 4vw, 42px);
}
.stats {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
}
.stat {
  min-width: 90px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  background: rgba(14, 31, 39, 0.9);
  border-radius: 12px;
  text-align: center;
}
.stat span {
  display: block;
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.stat strong {
  font-size: 24px;
  line-height: 1.2;
}
.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 12px 0 14px;
}
button {
  border: 1px solid var(--line);
  background: rgba(17, 31, 40, 0.9);
  color: var(--text);
  border-radius: 10px;
  padding: 10px 16px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.1s ease, border-color 0.2s ease, background 0.2s ease;
}
button:hover { border-color: var(--accent); }
button:active { transform: translateY(1px); }
button.primary { background: linear-gradient(180deg, #7ed4ff, #3b8ed8); color: #042740; }
button.tool.active {
  background: rgba(126, 231, 255, 0.18);
  border-color: var(--accent);
}
#gameCanvas {
  width: 100%;
  height: auto;
  display: block;
  background: linear-gradient(180deg, #0d2031 0%, #0c1421 100%);
  border-radius: 16px;
  border: 1px solid rgba(163, 207, 255, 0.22);
  box-shadow: inset 0 0 30px rgba(76, 128, 179, 0.15);
}
.message {
  margin-top: 14px;
  min-height: 28px;
  background: rgba(9, 20, 25, 0.8);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 10px 14px;
  color: var(--muted);
}
@media (max-width: 700px) {
  body { padding: 10px; }
  .game-shell { padding: 12px; }
  .topbar { display: block; }
  .stats { justify-content: flex-start; margin-top: 12px; }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const levelLabel = document.getElementById('levelLabel');
const savedLabel = document.getElementById('savedLabel');
const targetLabel = document.getElementById('targetLabel');
const buildLabel = document.getElementById('buildLabel');
const messageBox = document.getElementById('message');
const startBtn = document.getElementById('startBtn');
const resetBtn = document.getElementById('resetBtn');
const nextBtn = document.getElementById('nextBtn');
const buildBtn = document.getElementById('buildBtn');
const removeBtn = document.getElementById('removeBtn');

const world = {
  width: canvas.width,
  height: canvas.height,
  gravity: 0.36,
  terrain: [],
  structures: [],
  lemmings: [],
  hatch: { x: 60, y: 400 },
  castle: { x: 820, y: 410, width: 90, height: 90 },
  wormholes: [],
  activeTool: 'build',
  levelIndex: 0,
  lastTime: 0,
  started: false,
  completed: false,
  lastBuilds: 0,
  levelTarget: 5,
  saveCount: 0,
};

const LEVELS = [
  {
    name: 'Crag Crossing',
    hatch: { x: 70, y: 420 },
    castle: { x: 820, y: 360, width: 90, height: 120 },
    gaps: [{ x: 250, width: 95 }, { x: 500, width: 80 }, { x: 690, width: 70 }],
    platforms: [
      { x: 0, y: 500, width: 200, height: 44 },
      { x: 320, y: 500, width: 120, height: 44 },
      { x: 560, y: 500, width: 100, height: 44 },
      { x: 760, y: 500, width: 200, height: 44 },
    ],
    target: 4,
  },
  {
    name: 'Velvet Rift',
    hatch: { x: 80, y: 400 },
    castle: { x: 840, y: 330, width: 80, height: 150 },
    gaps: [{ x: 210, width: 110 }, { x: 430, width: 120 }, { x: 630, width: 150 }],
    platforms: [
      { x: 0, y: 500, width: 160, height: 44 },
      { x: 290, y: 510, width: 120, height: 34 },
      { x: 520, y: 470, width: 90, height: 74 },
      { x: 760, y: 500, width: 200, height: 44 },
    ],
    target: 6,
  },
  {
    name: 'Sunspire',
    hatch: { x: 70, y: 410 },
    castle: { x: 850, y: 310, width: 100, height: 180 },
    gaps: [{ x: 180, width: 120 }, { x: 370, width: 90 }, { x: 580, width: 140 }, { x: 770, width: 40 }],
    platforms: [
      { x: 0, y: 500, width: 150, height: 44 },
      { x: 230, y: 480, width: 120, height: 64 },
      { x: 470, y: 500, width: 100, height: 44 },
      { x: 705, y: 470, width: 110, height: 74 },
      { x: 860, y: 500, width: 100, height: 44 },
    ],
    target: 8,
  }
];

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function setMessage(text) {
  messageBox.textContent = text;
}

function makeLemming(x, y) {
  return {
    x,
    y,
    vx: 0.9 + Math.random() * 0.6,
    vy: 0,
    width: 14,
    height: 16,
    color: `hsl(${Math.floor(Math.random() * 45) + 180}, 70%, 70%)`,
    grounded: false,
    direction: 1,
    alive: true,
    reachedCastle: false,
    hasFallenOff: false,
    buildCooldown: 0,
    removeCooldown: 0,
  };
}

function loadLevel(index) {
  const level = LEVELS[index % LEVELS.length];
  const { hatch, castle, platforms, gaps } = level;

  world.levelIndex = index;
  world.hatch = { ...hatch };
  world.castle = { ...castle };
  world.levelTarget = level.target;
  world.terrain = platforms.map(p => ({ ...p, type: 'solid' }));
  world.structures = [];
  world.WALLS = gaps.map(g => ({ x: g.x, width: g.width, y: 0, height: canvas.height }));
  world.wormholes = [];
  world.started = false;
  world.completed = false;
  world.saveCount = 0;
  world.lemmings = [];
  world.lastBuilds = 0;

  for (let i = 0; i < 7; i += 1) {
    world.lemmings.push(makeLemming(hatch.x + 18 * i, hatch.y - 10));
  }

  levelLabel.textContent = String(index + 1);
  targetLabel.textContent = String(level.target);
  savedLabel.textContent = '0';
  buildLabel.textContent = '0';
  setMessage(`${level.name}: build bridges and escort the swarm to the castle.`);
}

function resetLevel() {
  loadLevel(world.levelIndex);
}

function selectTool(tool) {
  world.activeTool = tool;
  buildBtn.classList.toggle('active', tool === 'build');
  removeBtn.classList.toggle('active', tool === 'remove');
  setMessage(tool === 'build'
    ? 'Bridge tool active. Click a gap to lay planks.'
    : 'Removal tool active. Click a bridge section to remove it.');
}

function getBridgeLength() {
  return 36;
}

function placeBridge(x, y) {
  const targetX = clamp(Math.round(x / 20) * 20, 0, canvas.width - 30);
  const bridge = {
    x: targetX,
    y: clamp(y, 420, 500),
    width: getBridgeLength(),
    height: 12,
    type: 'bridge',
  };

  if (world.structures.some(b => Math.abs(b.x - bridge.x) < 18 && Math.abs(b.y - bridge.y) < 12)) {
    return;
  }

  world.structures.push(bridge);
  world.lastBuilds += 1;
  buildLabel.textContent = String(world.lastBuilds);
}

function removeBridge(x, y) {
  const index = world.structures.findIndex(b => {
    const hitX = x >= b.x && x <= b.x + b.width;
    const hitY = y >= b.y && y <= b.y + b.height;
    return hitX && hitY && b.type === 'bridge';
  });
  if (index >= 0) {
    world.structures.splice(index, 1);
  }
}

function startSwarm() {
  world.started = true;
  world.completed = false;
  setMessage('The swarm has started. Keep them moving toward the castle.');
}

function checkCastleArrival(lemming) {
  const castleRect = world.castle;
  const insideCastle = lemming.x + lemming.width > castleRect.x && lemming.x < castleRect.x + castleRect.width && lemming.y + lemming.height > castleRect.y;
  if (insideCastle && !lemming.reachedCastle) {
    lemming.reachedCastle = true;
    lemming.alive = false;
    world.saveCount += 1;
    savedLabel.textContent = String(world.saveCount);
    if (world.saveCount >= world.levelTarget) {
      world.completed = true;
      setMessage(`You saved the swarm! ${world.levelTarget} rescued. Ready for next level.`);
      if (world.levelIndex < LEVELS.length - 1) {
        nextBtn.disabled = false;
      }
    }
  }
}

function resolveTerrain(lemming) {
  const allGround = [...world.terrain, ...world.structures].filter(platform => platform.type === 'solid' || platform.type === 'bridge');
  let grounded = false;

  for (const platform of allGround) {
    const withinHorizontal = lemming.x + lemming.width > platform.x && lemming.x < platform.x + platform.width;
    const topTouch = lemming.y + lemming.height >= platform.y && lemming.y + lemming.height <= platform.y + platform.height + 12;
    if (withinHorizontal && topTouch && lemming.vy >= 0) {
      lemming.y = platform.y - lemming.height;
      lemming.vy = 0;
      lemming.grounded = true;
      grounded = true;
      break;
    }
  }

  if (!grounded) {
    lemming.grounded = false;
  }

  if (lemming.y > canvas.height + 50) {
    lemming.alive = false;
    lemming.hasFallenOff = true;
  }
}

function updateAIs() {
  if (!world.started) return;

  for (const lemming of world.lemmings) {
    if (!lemming.alive) continue;

    if (lemming.grounded) {
      const collisionAhead = world.terrain.some(platform => {
        const rectX = platform.x;
        const rectW = platform.width;
        return lemming.x + lemming.width + 2 > rectX && lemming.x < rectX + rectW && lemming.y + lemming.height >= platform.y - 4;
      });

      if (collisionAhead && lemming.x + lemming.width > world.castle.x - 30) {
        lemming.direction = -1;
      }
    }

    lemming.vy += world.gravity;
    lemming.x += lemming.vx * lemming.direction;
    lemming.y += lemming.vy;

    if (lemming.x < 0) {
      lemming.x = 0;
      lemming.direction *= -1;
    }
    if (lemming.x + lemming.width > canvas.width) {
      lemming.x = canvas.width - lemming.width;
      lemming.direction *= -1;
    }

    if (lemming.grounded && Math.random() < 0.02) {
      lemming.direction *= -1;
    }

    resolveTerrain(lemming);

    if (!lemming.grounded && !lemming.hasFallenOff) {
      lemming.direction = lemming.direction || 1;
    }

    if (lemming.x + lemming.width < world.castle.x && lemming.grounded && Math.random() < 0.006) {
      lemming.direction *= -1;
    }

    const castleFront = world.castle.x - 30;
    if (lemming.x > castleFront && lemming.grounded) {
      lemming.direction = -1;
    }

    checkCastleArrival(lemming);
  }

  world.lemmings = world.lemmings.filter(le => le.alive || (!le.reachedCastle && !le.hasFallenOff));
}

function drawBackground() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, '#0d2031');
  sky.addColorStop(1, '#091923');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (let i = 0; i < 22; i += 1) {
    const x = (i * 57 + 40) % canvas.width;
    const y = 30 + (i * 29) % 160;
    ctx.fillStyle = 'rgba(255,255,255,0.6)';
    ctx.fillRect(x, y, 2, 2);
  }

  ctx.fillStyle = '#17324a';
  ctx.fillRect(0, 490, canvas.width, 54);

  for (const platform of world.terrain) {
    ctx.fillStyle = '#375f73';
    ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
  }

  for (const structure of world.structures) {
    ctx.fillStyle = '#e3b66a';
    ctx.fillRect(structure.x, structure.y, structure.width, structure.height);
    ctx.fillStyle = '#8a5c2a';
    ctx.fillRect(structure.x + 6, structure.y + 3, structure.width - 12, 3);
  }

  const castle = world.castle;
  ctx.fillStyle = '#d7c58e';
  ctx.fillRect(castle.x, castle.y, castle.width, castle.height);
  ctx.fillStyle = '#a29472';
  ctx.fillRect(castle.x + 18, castle.y + 18, castle.width - 36, castle.height - 16);
  ctx.fillStyle = '#ffd166';
  for (let i = 0; i < 5; i += 1) {
    ctx.fillRect(castle.x + 12 + i * 16, castle.y - 12, 7, 12);
  }

  const hatch = world.hatch;
  ctx.fillStyle = '#7ce9f5';
  ctx.fillRect(hatch.x - 10, hatch.y - 10, 28, 28);
  ctx.fillStyle = '#c9f5ff';
  ctx.beginPath();
  ctx.arc(hatch.x + 4, hatch.y - 18, 16, 0, Math.PI * 2);
  ctx.fill();

  for (const gap of world.WALLS || []) {
    ctx.fillStyle = 'rgba(255, 129, 96, 0.25)';
    ctx.fillRect(gap.x, gap.y, gap.width, gap.height);
  }
}

function drawLemmings() {
  for (const lemming of world.lemmings) {
    if (!lemming.alive) continue;
    ctx.fillStyle = lemming.color;
    ctx.fillRect(lemming.x, lemming.y, lemming.width, lemming.height);
    ctx.fillStyle = '#123';
    ctx.fillRect(lemming.x + 3, lemming.y - 3, 3, 3);
    ctx.fillRect(lemming.x + 9, lemming.y - 3, 3, 3);
  }
}

function drawHUD() {
  ctx.fillStyle = 'rgba(7, 16, 21, 0.45)';
  ctx.fillRect(16, 16, 240, 44);
  ctx.fillStyle = '#dff7ff';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Rescue ${world.saveCount}/${world.levelTarget}`, 28, 42);
}

function draw() {
  drawBackground();
  drawLemmings();
  drawHUD();
}

function step(timestamp) {
  const dt = Math.min((timestamp - world.lastTime) / 16.67 || 1, 2);
  world.lastTime = timestamp;

  if (world.started && !world.completed) {
    updateAIs();
  }

  draw();
  requestAnimationFrame(step);
}

canvas.addEventListener('click', event => {
  const rect = canvas.getBoundingClientRect();
  const x = ((event.clientX - rect.left) / rect.width) * canvas.width;
  const y = ((event.clientY - rect.top) / rect.height) * canvas.height;

  if (world.activeTool === 'build') {
    const buildY = clamp(y, 420, 500);
    placeBridge(x, buildY);
    setMessage('Bridge placed. Start the swarm to see if it is enough.');
  } else {
    removeBridge(x, y);
    setMessage('Bridge section removed.');
  }
});

buildBtn.addEventListener('click', () => selectTool('build'));
removeBtn.addEventListener('click', () => selectTool('remove'));
startBtn.addEventListener('click', startSwarm);
resetBtn.addEventListener('click', resetLevel);
nextBtn.addEventListener('click', () => {
  const nextIndex = (world.levelIndex + 1) % LEVELS.length;
  loadLevel(nextIndex);
  nextBtn.disabled = true;
});

nextBtn.disabled = true;
loadLevel(0);
selectTool('build');
requestAnimationFrame(step);

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const levelLabel = document.getElementById('levelLabel');
const savedLabel = document.getElementById('savedLabel');
const targetLabel = document.getElementById('targetLabel');
const buildLabel = document.getElementById('buildLabel');
const messageBox = document.getElementById('message');
const startBtn = document.getElementById('startBtn');
const resetBtn = document.getElementById('resetBtn');
const nextBtn = document.getElementById('nextBtn');
const buildBtn = document.getElementById('buildBtn');
const removeBtn = document.getElementById('removeBtn');

const state = {
  levelIndex: 0,
  started: false,
  completed: false,
  activeTool: 'build',
  saveCount: 0,
  builds: 0,
  target: 4,
  terrain: [],
  gaps: [],
  bridges: [],
  lemmings: [],
  hatch: { x: 48, y: 404 },
  castle: { x: 820, y: 344, width: 84, height: 156 },
  lastTime: 0,
};

const LEVELS = [
  {
    name: 'Crag Crossing',
    hatch: { x: 48, y: 404 },
    castle: { x: 820, y: 330, width: 84, height: 170 },
    target: 4,
    platforms: [
      { x: 0, y: 500, width: 180, height: 44 },
      { x: 280, y: 500, width: 150, height: 44 },
      { x: 520, y: 500, width: 120, height: 44 },
      { x: 750, y: 500, width: 210, height: 44 },
    ],
    gaps: [
      { x: 180, width: 100 },
      { x: 430, width: 90 },
      { x: 640, width: 110 },
    ],
  },
  {
    name: 'Velvet Rift',
    hatch: { x: 52, y: 398 },
    castle: { x: 835, y: 320, width: 88, height: 180 },
    target: 6,
    platforms: [
      { x: 0, y: 500, width: 160, height: 44 },
      { x: 280, y: 500, width: 110, height: 44 },
      { x: 470, y: 470, width: 100, height: 74 },
      { x: 700, y: 500, width: 200, height: 44 },
    ],
    gaps: [
      { x: 160, width: 120 },
      { x: 390, width: 80 },
      { x: 570, width: 130 },
    ],
  },
  {
    name: 'Sunspire',
    hatch: { x: 52, y: 400 },
    castle: { x: 850, y: 300, width: 96, height: 200 },
    target: 8,
    platforms: [
      { x: 0, y: 500, width: 140, height: 44 },
      { x: 220, y: 485, width: 120, height: 59 },
      { x: 430, y: 500, width: 110, height: 44 },
      { x: 640, y: 470, width: 120, height: 74 },
      { x: 840, y: 500, width: 120, height: 44 },
    ],
    gaps: [
      { x: 140, width: 80 },
      { x: 340, width: 90 },
      { x: 540, width: 100 },
      { x: 760, width: 80 },
    ],
  },
];

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function setMessage(text) {
  messageBox.textContent = text;
}

function makeLemming(x, y) {
  return {
    x,
    y,
    width: 14,
    height: 16,
    vx: 0,
    vy: 0,
    direction: 1,
    color: `hsl(${180 + Math.random() * 40}, 70%, 66%)`,
    grounded: false,
    alive: true,
    saved: false,
  };
}

function getSurfaceAt(x, y) {
  const probes = [...state.terrain, ...state.bridges];
  let best = null;

  for (const platform of probes) {
    const withinX = x >= platform.x && x <= platform.x + platform.width;
    if (withinX && (!best || platform.y < best.y)) {
      best = { ...platform, y: platform.y };
    }
  }

  if (!best) return null;
  return best.y <= y + 12 ? best : null;
}

function spawnLemmings() {
  const count = state.target + 2;
  state.lemmings = [];
  for (let i = 0; i < count; i += 1) {
    state.lemmings.push(makeLemming(state.hatch.x + i * 14, state.hatch.y));
  }
}

function updateHud() {
  levelLabel.textContent = String(state.levelIndex + 1);
  savedLabel.textContent = String(state.saveCount);
  targetLabel.textContent = String(state.target);
  buildLabel.textContent = String(state.builds);
}

function loadLevel(levelIndex) {
  const level = LEVELS[levelIndex % LEVELS.length];
  state.levelIndex = levelIndex;
  state.hatch = { ...level.hatch };
  state.castle = { ...level.castle };
  state.target = level.target;
  state.terrain = level.platforms.map(platform => ({ ...platform }));
  state.gaps = level.gaps.map(gap => ({ ...gap }));
  state.bridges = [];
  state.started = false;
  state.completed = false;
  state.saveCount = 0;
  state.builds = 0;
  spawnLemmings();
  updateHud();
  nextBtn.disabled = true;
  setMessage(`${level.name}: click a gap to build a bridge, then start the swarm.`);
}

function selectTool(tool) {
  state.activeTool = tool;
  buildBtn.classList.toggle('active', tool === 'build');
  removeBtn.classList.toggle('active', tool === 'remove');
  setMessage(tool === 'build' ? 'Build mode: click directly over a red gap to place a bridge.' : 'Remove mode: click a bridge to break it apart.');
}

function placeBridge(x, y) {
  const gap = state.gaps.find((piece) => x >= piece.x && x <= piece.x + piece.width && y >= 440 && y <= 520);
  if (!gap) {
    setMessage('Not over a gap. Build across the dark red chasm only.');
    return;
  }

  const width = clamp(gap.width - 10, 26, 90);
  const bridgeX = clamp(x - width / 2, gap.x + 6, gap.x + gap.width - width - 4);
  const bridge = {
    x: bridgeX,
    y: 500,
    width,
    height: 14,
    type: 'bridge',
  };

  const overlaps = state.bridges.some(existing => {
    const overlapX = bridge.x < existing.x + existing.width && bridge.x + bridge.width > existing.x;
    const overlapY = bridge.y < existing.y + existing.height && bridge.y + bridge.height > existing.y;
    return overlapX && overlapY;
  });
  if (overlaps) {
    setMessage('A bridge is already there. Remove it or place a new one elsewhere.');
    return;
  }

  state.bridges.push(bridge);
  state.builds += 1;
  updateHud();
  setMessage('Bridge laid. The swarm can now cross that gap.');
}

function removeBridge(x, y) {
  const index = state.bridges.findIndex((bridge) => {
    return x >= bridge.x && x <= bridge.x + bridge.width && y >= bridge.y && y <= bridge.y + bridge.height;
  });

  if (index === -1) {
    setMessage('Nothing to remove there.');
    return;
  }

  state.bridges.splice(index, 1);
  state.builds = Math.max(0, state.builds - 1);
  updateHud();
  setMessage('Bridge removed. The path is open again.');
}

function startSwarm() {
  state.started = true;
  setMessage('The swarm is moving. Keep the bridge path safe.');
}

function registerSavedLemming(lemming) {
  if (lemming.saved) return;
  lemming.saved = true;
  lemming.alive = false;
  state.saveCount += 1;
  updateHud();

  if (state.saveCount >= state.target) {
    state.completed = true;
    state.started = false;
    setMessage(`Goal reached! ${state.saveCount} rescued. You can move to the next level.`);
    nextBtn.disabled = state.levelIndex >= LEVELS.length - 1;
    if (state.levelIndex < LEVELS.length - 1) nextBtn.disabled = false;
  }
}

function updateLemmings() {
  if (!state.started) return;

  for (const lemming of state.lemmings) {
    if (!lemming.alive) continue;

    const support = getSurfaceAt(lemming.x + lemming.width / 2, lemming.y + lemming.height + 1);

    if (support) {
      lemming.grounded = true;
      lemming.y = support.y - lemming.height;
      lemming.vy = 0;
      const step = 1.2;
      const nextX = lemming.x + lemming.direction * step;
      const futureSupport = getSurfaceAt(nextX + lemming.width / 2, lemming.y + lemming.height + 1);

      if (nextX <= 0 || nextX + lemming.width >= canvas.width) {
        lemming.direction *= -1;
      }

      if (!futureSupport && lemming.x + lemming.width > state.castle.x - 30) {
        lemming.direction = -1;
      }

      if (support.y === 500 && Math.random() < 0.015 && lemming.x + lemming.width > 300) {
        lemming.direction *= -1;
      }

      lemming.x += lemming.direction * step;

      if (lemming.x < state.castle.x - 30 && Math.random() < 0.01) {
        lemming.direction *= -1;
      }
    } else {
      lemming.grounded = false;
      lemming.vy += 0.34;
      lemming.y += lemming.vy;
    }

    const castleRect = state.castle;
    const insideCastle = lemming.x + lemming.width > castleRect.x && lemming.x < castleRect.x + castleRect.width && lemming.y + lemming.height > castleRect.y && lemming.y < castleRect.y + castleRect.height;
    if (insideCastle) {
      registerSavedLemming(lemming);
      continue;
    }

    if (lemming.y > canvas.height + 40) {
      lemming.alive = false;
    }
  }

  state.lemmings = state.lemmings.filter(lemming => lemming.alive || !lemming.saved);
}

function drawBackground() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, '#0c1d2f');
  sky.addColorStop(1, '#071521');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (let i = 0; i < 24; i += 1) {
    const x = ((i * 61) % canvas.width) + 24;
    const y = 40 + ((i * 47) % 150);
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.fillRect(x, y, 2, 2);
  }

  ctx.fillStyle = '#1c3745';
  ctx.fillRect(0, 500, canvas.width, 44);

  for (const platform of state.terrain) {
    ctx.fillStyle = '#4d78a6';
    ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
    ctx.fillStyle = '#7bb9d8';
    ctx.fillRect(platform.x, platform.y, platform.width, 6);
  }

  for (const gap of state.gaps) {
    ctx.fillStyle = 'rgba(255, 112, 88, 0.35)';
    ctx.fillRect(gap.x, 440, gap.width, 80);
  }

  for (const bridge of state.bridges) {
    ctx.fillStyle = '#e9c46a';
    ctx.fillRect(bridge.x, bridge.y, bridge.width, bridge.height);
    ctx.fillStyle = '#b2732d';
    ctx.fillRect(bridge.x + 4, bridge.y + 2, bridge.width - 8, 4);
  }

  const castle = state.castle;
  ctx.fillStyle = '#d9d3a7';
  ctx.fillRect(castle.x, castle.y, castle.width, castle.height);
  ctx.fillStyle = '#a89d72';
  ctx.fillRect(castle.x + 18, castle.y + 20, castle.width - 36, castle.height - 30);
  ctx.fillStyle = '#ffd166';
  for (let i = 0; i < 5; i += 1) {
    ctx.fillRect(castle.x + 10 + i * 15, castle.y - 14, 8, 12);
  }

  const hatch = state.hatch;
  ctx.fillStyle = '#6fe8ff';
  ctx.fillRect(hatch.x - 10, hatch.y - 14, 28, 32);
  ctx.fillStyle = '#dffcff';
  ctx.beginPath();
  ctx.arc(hatch.x + 4, hatch.y - 18, 15, 0, Math.PI * 2);
  ctx.fill();
}

function drawLemmings() {
  for (const lemming of state.lemmings) {
    if (!lemming.alive) continue;
    ctx.fillStyle = lemming.color;
    ctx.fillRect(lemming.x, lemming.y, lemming.width, lemming.height);
    ctx.fillStyle = '#132730';
    ctx.fillRect(lemming.x + 3, lemming.y - 2, 3, 3);
    ctx.fillRect(lemming.x + 9, lemming.y - 2, 3, 3);
  }
}

function drawUiOverlay() {
  ctx.fillStyle = 'rgba(9, 18, 26, 0.44)';
  ctx.fillRect(18, 18, 240, 42);
  ctx.fillStyle = '#ebf8ff';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Saved ${state.saveCount}/${state.target}`, 32, 44);
}

function render() {
  drawBackground();
  drawLemmings();
  drawUiOverlay();
}

function step(timestamp) {
  const delta = Math.min((timestamp - state.lastTime) / 16.67 || 1, 2);
  state.lastTime = timestamp;

  if (state.started && !state.completed) {
    for (let i = 0; i < delta; i += 1) {
      updateLemmings();
    }
  }

  render();
  requestAnimationFrame(step);
}

function handleCanvasClick(event) {
  const rect = canvas.getBoundingClientRect();
  const x = ((event.clientX - rect.left) / rect.width) * canvas.width;
  const y = ((event.clientY - rect.top) / rect.height) * canvas.height;

  if (state.activeTool === 'build') {
    placeBridge(x, y);
  } else {
    removeBridge(x, y);
  }
}

buildBtn.addEventListener('click', () => selectTool('build'));
removeBtn.addEventListener('click', () => selectTool('remove'));
startBtn.addEventListener('click', startSwarm);
resetBtn.addEventListener('click', () => loadLevel(state.levelIndex));
nextBtn.addEventListener('click', () => {
  const nextIndex = state.levelIndex + 1;
  loadLevel(nextIndex);
});
canvas.addEventListener('click', handleCanvasClick);

selectTool('build');
loadLevel(0);
requestAnimationFrame(step);

